// 先证明期次与原 LE 来源，再在原 Shop 回放中消费真实支付；不足判断扣除原员工尚未赚取预约。
#include "private_shop_daily_rent_financial.hpp"
namespace hanmo::resident {namespace {
template<class T>Outcome<T> fail(const StableId& code){return {false,{},common_failure(code).error};}
bool before(const CommonStore& c,const StableId& a,const StableId& b){const auto& order=c.state().facts.order();const auto first=std::find(order.begin(),order.end(),a),last=std::find(order.begin(),order.end(),b);return first!=order.end()&&last!=order.end()&&first<last;}
Outcome<Integer> wage_reserved_before(const PrivateShopContext& x,const PrivateShopRecord& shop,const StableId& boundary){Integer held=0;for(const auto& row:x.state.operations.rows()){const auto& op=row.second;if(op.shop_id!=shop.id||op.staff_contract_id.empty()||!before(x.common,op.id,boundary)||(!op.result_fact_id.empty()&&before(x.common,op.result_fact_id,boundary)))continue;const auto* staff=x.state.staff.contracts.find(op.staff_contract_id);if(!staff||staff->terms.shop_id!=shop.id||staff->terms.payer_wallet_id!=shop.wallet_id)return fail<Integer>("PrivateShopRentWageSourceMismatch");Integer paid=0;for(const auto& service:x.state.staff.services.rows())if(service.second.operation_id==op.id&&before(x.common,service.second.payment_id,boundary)){const auto* payment=x.economy.payments.find(service.second.payment_id);if(!payment||payment->amount!=service.second.amount||payment->amount<=0||__builtin_add_overflow(paid,payment->amount,&paid))return fail<Integer>("PrivateShopRentWageSourceMismatch");}if(paid>3||__builtin_add_overflow(held,3-paid,&held))return fail<Integer>("PrivateShopRentWageSourceMismatch");}return {true,held,{}};}
}
Status validate_private_shop_daily_rent_selection(const PrivateShopContext& x){if(bool(x.daily_rent_catalog)!=bool(x.daily_rent))return common_failure("PrivateShopDailyRentPairRequired");if(!x.daily_rent){if(x.rent_executors)return common_failure("PrivateShopDailyRentPairRequired");return validate_private_shop_daily_rent_layout(x.common,nullptr);}PrivateShopDailyRentContext context{x,*x.daily_rent_catalog,*x.daily_rent,x.rent_executors,x.rent_death_origin};return validate_private_shop_daily_rent_authority(context);}
Outcome<std::optional<PrivateShopRentCashEffect>> private_shop_rent_cash_effect(const PrivateShopContext& x,const PrivateShopRecord& shop,const StableId& id,Integer cash){if(!x.daily_rent)return {true,std::nullopt,{}};if(cash<0)return fail<std::optional<PrivateShopRentCashEffect>>("PrivateShopRentCashHistoryMismatch");PrivateShopRentCashEffect effect;
 if(const auto* a=x.daily_rent->assessments.find(id)){if(a->shop_id!=shop.id)return {true,std::nullopt,{}};auto reserved=wage_reserved_before(x,shop,id);if(!reserved.ok)return {false,{},reserved.error};if(cash<reserved.value)return fail<std::optional<PrivateShopRentCashEffect>>("PrivateShopRentCashHistoryMismatch");const bool affordable=cash-reserved.value>=shop.terms.daily_rent;if(affordable!=!a->automatic_payment_fact_id.empty())return fail<std::optional<PrivateShopRentCashEffect>>("PrivateShopRentFundingHistoryMismatch");effect.tick=a->tick;effect.allocated_sources={{a->id,private_shop_rent_assessed_kind},{a->arrear_id,"local_due"}};if(!affordable)effect.status="suspended";return {true,std::move(effect),{}};}
 if(const auto* p=x.daily_rent->payments.find(id)){const auto* a=x.daily_rent->assessments.find(p->assessment_fact_id);if(!a)return fail<std::optional<PrivateShopRentCashEffect>>("PrivateShopRentPaymentAssessmentMissing");if(a->shop_id!=shop.id)return {true,std::nullopt,{}};const auto* payment=x.economy.payments.find(p->local_payment_id);if(!payment||payment->amount!=shop.terms.daily_rent)return fail<std::optional<PrivateShopRentCashEffect>>("PrivateShopRentOriginalPaymentMismatch");const bool store=p->funding_kind=="automatic_shop"||p->funding_kind=="proprietor_shop";if(store){auto reserved=wage_reserved_before(x,shop,id);if(!reserved.ok)return {false,{},reserved.error};if(cash<reserved.value||cash-reserved.value<payment->amount)return fail<std::optional<PrivateShopRentCashEffect>>("PrivateShopRentCashHistoryMismatch");effect.shop_cash_delta=-payment->amount;}effect.tick=p->tick;effect.allocated_sources={{p->id,private_shop_rent_paid_kind},{payment->id,"local_payment"}};effect.last_local_payment_id=payment->id;return {true,std::move(effect),{}};}
 if(const auto* r=x.daily_rent->resumptions.find(id)){if(r->shop_id!=shop.id)return {true,std::nullopt,{}};effect.tick=r->tick;effect.status="open";effect.allocated_sources={{r->id,private_shop_rent_resumed_kind}};return {true,std::move(effect),{}};}
 return {true,std::nullopt,{}};
}
Outcome<bool> private_shop_rent_use_current(const PrivateShopContext& x,const StableId& id){auto valid=validate_private_shop_daily_rent_selection(x);if(!valid.ok)return {false,false,valid.error};if(!x.daily_rent)return {true,true,{}};auto ledger=read_private_shop_rent_ledger(x.common,x.economy,x.state,*x.daily_rent_catalog,*x.daily_rent,id,x.phase);if(!ledger.ok)return {false,false,ledger.error};return {true,!ledger.value.suspended&&!ledger.value.closed&&ledger.value.pending_arrear_id.empty()&&x.common.tick()<ledger.value.through_tick,{}};}
}
